"use client";

import { cn } from "@/lib/utils";
import React, { forwardRef, useCallback, useEffect, useRef, useState } from "react";
import { getThemeStyles } from "./timeline-kit-theme";
import { useScrollProgress } from "./timeline-scroll";

export type TimelinePathColor =
  | "primary"
  | "indigo"
  | "rose"
  | "emerald"
  | "blue"
  | "violet"
  | "zinc"
  | (string & {});

export interface TimelinePathItem {
  id: string | number;
  title: string;
  /** Small label above the title, such as a phase or a date. */
  date?: string;
  description?: string;
  icon?: React.ElementType;
}

export interface TimelinePathBlockProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  items: TimelinePathItem[];
  color?: TimelinePathColor;
  /** The stop in focus before anything scrolls. */
  defaultIndex?: number;
  /** Fires when the stop in focus changes. */
  onIndexChange?: (index: number) => void;
  /** Smooths the line draw and the card fades. */
  animate?: boolean;
}

type Point = { x: number; y: number };

/** Where a node sits from the top of its row, in px. */
const NODE_TOP = 30;
/** Container width, in px, from which the path winds between two lanes. */
const WIDE = 640;

/** One S-curve from `a` to `b`, leaving and arriving vertically. */
const curve = (a: Point, b: Point) => {
  const mid = (b.y - a.y) / 2;
  return `M${a.x} ${a.y}C${a.x} ${a.y + mid} ${b.x} ${b.y - mid} ${b.x} ${b.y}`;
};

/**
 * A scroll-linked timeline on a winding path. The line draws itself from stop
 * to stop as the page (or the panel the timeline sits in) scrolls, a glowing
 * head leads it, and each card lights up when the head reaches it.
 *
 * It reads the scroll of its nearest scrolling ancestor, else the page. Click
 * a card to scroll its stop into focus. On a narrow column the path hugs the
 * left edge and the cards stack to its right.
 */
export const TimelinePathBlock = forwardRef<HTMLDivElement, TimelinePathBlockProps>(
  (
    {
      items,
      color = "primary",
      defaultIndex = 0,
      onIndexChange,
      animate = true,
      className,
      style: styleProp,
      ...props
    },
    ref,
  ) => {
    const { style } = getThemeStyles(color as string);
    const hostRef = useRef<HTMLDivElement | null>(null);
    const setRefs = useCallback(
      (node: HTMLDivElement | null) => {
        hostRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      },
      [ref],
    );
    const listRef = useRef<HTMLOListElement>(null);
    const segmentRefs = useRef<(SVGPathElement | null)[]>([]);
    const headRef = useRef<SVGCircleElement>(null);
    const [geometry, setGeometry] = useState<{
      width: number;
      height: number;
      wide: boolean;
      points: Point[];
    } | null>(null);

    const { progress, active, goTo } = useScrollProgress(hostRef, items.length, {
      focus: 0.45,
      initial: defaultIndex,
      onChange: onIndexChange,
    });

    // Measure the rows, then place a node on each one.
    useEffect(() => {
      const list = listRef.current;
      if (!list) return;
      const measure = () => {
        const width = list.clientWidth;
        const wide = width >= WIDE;
        // Only the rows: the path's own <svg> is a child of the list too.
        const points = Array.from(
          list.querySelectorAll<HTMLElement>(":scope > li"),
          (row, i) => ({
            x: wide ? width * (i % 2 === 0 ? 0.42 : 0.58) : 16 + (i % 2) * 8,
            y: row.offsetTop + NODE_TOP,
          }),
        );
        setGeometry({ width, height: list.clientHeight, wide, points });
      };
      measure();
      const observer = new ResizeObserver(measure);
      observer.observe(list);
      return () => observer.disconnect();
    }, [items]);

    // Park the glowing head on the segment the focus line is crossing.
    useEffect(() => {
      const head = headRef.current;
      if (!head || !geometry || geometry.points.length < 2) return;
      const index = Math.min(Math.floor(progress), geometry.points.length - 2);
      const segment = segmentRefs.current[index];
      if (!segment) return;
      const t = Math.min(1, Math.max(0, progress - index));
      const point = segment.getPointAtLength(segment.getTotalLength() * t);
      head.setAttribute("cx", String(point.x));
      head.setAttribute("cy", String(point.y));
    }, [progress, geometry]);

    return (
      <div
        ref={setRefs}
        className={cn(
          "@container/timeline w-full",
          !animate && "[&_*]:!transition-none",
          className,
        )}
        style={{ ...style, ...styleProp }}
        {...props}
      >
        <ol ref={listRef} className="relative m-0 list-none p-0">
          {geometry && geometry.points.length > 0 && (
            <svg
              aria-hidden
              width={geometry.width}
              height={geometry.height}
              viewBox={`0 0 ${geometry.width} ${geometry.height}`}
              className="pointer-events-none absolute inset-0 overflow-visible"
            >
              {geometry.points.slice(0, -1).map((point, i) => {
                const d = curve(point, geometry.points[i + 1]);
                const fill = Math.min(1, Math.max(0, progress - i));
                return (
                  <g key={i}>
                    <path d={d} fill="none" className="stroke-border" strokeWidth={2} />
                    <path
                      ref={(el) => {
                        segmentRefs.current[i] = el;
                      }}
                      d={d}
                      fill="none"
                      pathLength={1}
                      strokeWidth={2}
                      strokeDasharray="1 1"
                      strokeDashoffset={1 - fill}
                      className="stroke-[var(--timeline-color)]"
                    />
                  </g>
                );
              })}
              {geometry.points.map((point, i) => {
                const reached = i <= active;
                return (
                  <g key={i} transform={`translate(${point.x} ${point.y})`}>
                    {i === active && (
                      <circle
                        r={17}
                        className="fill-[var(--timeline-color)]"
                        opacity={0.18}
                      />
                    )}
                    <circle
                      r={9}
                      strokeWidth={2}
                      className={cn(
                        "fill-background transition-colors duration-500",
                        reached ? "stroke-[var(--timeline-color)]" : "stroke-border",
                      )}
                    />
                    <circle
                      r={3.5}
                      className={cn(
                        "transition-colors duration-500",
                        reached
                          ? "fill-[var(--timeline-color)]"
                          : "fill-muted-foreground/40",
                      )}
                    />
                  </g>
                );
              })}
              {geometry.points.length > 1 && (
                <circle
                  ref={headRef}
                  r={4.5}
                  cx={geometry.points[0].x}
                  cy={geometry.points[0].y}
                  className="fill-[var(--timeline-color)]"
                  style={{ filter: "drop-shadow(0 0 7px var(--timeline-color))" }}
                />
              )}
            </svg>
          )}

          {items.map((item, index) => {
            const Icon = item.icon;
            const current = index === active;
            const onLeft = index % 2 === 0;
            return (
              <li
                key={item.id}
                className="relative pb-14 pl-12 last:pb-0 @xl/timeline:pl-0"
              >
                <span
                  data-tl-anchor
                  aria-hidden
                  className="absolute top-[30px] left-0 size-px"
                />
                <button
                  type="button"
                  onClick={() => goTo(index)}
                  aria-current={current ? "step" : undefined}
                  className={cn(
                    "block w-full rounded-2xl border bg-card/70 p-5 text-left backdrop-blur-sm outline-none transition-all duration-500 focus-visible:ring-2 focus-visible:ring-[var(--timeline-color)] @xl/timeline:w-[calc(42%-2.25rem)]",
                    onLeft ? "@xl/timeline:mr-auto" : "@xl/timeline:ml-auto",
                    current
                      ? "border-[color-mix(in_oklab,var(--timeline-color)_45%,transparent)] opacity-100 shadow-[0_8px_40px_-12px_var(--timeline-glow)]"
                      : "border-border opacity-55",
                  )}
                >
                  <span className="flex items-center gap-2.5">
                    {Icon && (
                      <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-[color-mix(in_oklab,var(--timeline-color)_14%,transparent)] text-[var(--timeline-color)]">
                        <Icon aria-hidden className="size-4" />
                      </span>
                    )}
                    {item.date && (
                      <span className="font-mono text-xs tracking-[0.14em] text-muted-foreground uppercase">
                        {item.date}
                      </span>
                    )}
                  </span>
                  <span className="mt-3 block text-lg font-semibold tracking-tight text-foreground">
                    {item.title}
                  </span>
                  {item.description && (
                    <span className="mt-1.5 block text-sm/6 text-muted-foreground">
                      {item.description}
                    </span>
                  )}
                </button>
              </li>
            );
          })}
        </ol>
      </div>
    );
  },
);
TimelinePathBlock.displayName = "TimelinePathBlock";

"use client";

import type React from "react";

/**
 * Accent colour for the timeline family. Everything reads three CSS variables
 * set on the component's root (`--timeline-color`, `--timeline-on-color`,
 * `--timeline-glow`), so plain classes, SVG strokes and `color-mix()` glows all
 * follow the same accent. `primary` follows the theme token and so retints
 * with every preset.
 */
const NAMED: Record<string, { color: string; on: string }> = {
  primary: { color: "var(--primary)", on: "var(--primary-foreground)" },
  indigo: { color: "#6366f1", on: "#ffffff" },
  rose: { color: "#f43f5e", on: "#ffffff" },
  emerald: { color: "#10b981", on: "#ffffff" },
  blue: { color: "#3b82f6", on: "#ffffff" },
  violet: { color: "#8b5cf6", on: "#ffffff" },
  zinc: { color: "var(--foreground)", on: "var(--background)" },
};

/** Class names that read the variables above. */
const THEME: Record<string, string> = {
  bg: "bg-[var(--timeline-color)]",
  on: "text-[var(--timeline-on-color)]",
  text: "text-[var(--timeline-color)]",
  border: "border-[var(--timeline-color)]",
  glow: "shadow-[0_0_15px_var(--timeline-glow)]",
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

const relLuminance = (rgb: string) => {
  const [r, g, b] = rgb.split(",").map((n) => {
    const v = Number(n.trim()) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

const vars = (color: string, on: string, glow: string) =>
  ({
    "--timeline-color": color,
    "--timeline-on-color": on,
    "--timeline-glow": glow,
  }) as React.CSSProperties;

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: THEME,
      style: vars(
        color,
        relLuminance(rgb) > 0.45 ? "#09090b" : "#ffffff",
        `rgba(${rgb}, 0.5)`,
      ),
    };
  }
  const named = NAMED[color] ?? NAMED.primary;
  return {
    theme: THEME,
    style: vars(
      named.color,
      named.on,
      `color-mix(in oklab, ${named.color} 50%, transparent)`,
    ),
  };
};

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/** Anything with a `current` element, so both `useRef` flavours fit. */
type ElementRef = { current: HTMLElement | null };

const clamp = (n: number, min: number, max: number) =>
  Math.min(max, Math.max(min, n));

/** True while the user asks the OS for less motion. */
export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return reduced;
}

/**
 * The index a timeline is showing, clamped to the item count. `onChange` fires
 * when it moves, not on mount.
 */
export function useActiveIndex(
  count: number,
  initial = 0,
  onChange?: (index: number) => void,
) {
  const [raw, setRaw] = useState(initial);
  const active = clamp(raw, 0, Math.max(0, count - 1));
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);
  const mounted = useRef(false);
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    onChangeRef.current?.(active);
  }, [active]);
  const set = useCallback(
    (next: number) => setRaw(clamp(next, 0, Math.max(0, count - 1))),
    [count],
  );
  return [active, set] as const;
}

/** The nearest ancestor that scrolls on its own, or null for the page. */
function scrollParentOf(el: HTMLElement | null): HTMLElement | null {
  const doc = el?.ownerDocument;
  let node = el?.parentElement ?? null;
  while (node && doc && node !== doc.body && node !== doc.documentElement) {
    const { overflowY } = getComputedStyle(node);
    if (/(auto|scroll|overlay)/.test(overflowY) && node.scrollHeight > node.clientHeight) {
      return node;
    }
    node = node.parentElement;
  }
  return null;
}

/** What scrolls under an element, in that element's own coordinates. */
interface Viewport {
  /** Top edge of the visible area, in the element's `getBoundingClientRect` space. */
  top: number;
  height: number;
  scrolled: number;
  max: number;
  /** True when the element sits in a frame that does not scroll itself. */
  framed: boolean;
  scrollBy: (dy: number, behavior: ScrollBehavior) => void;
  /** Documents whose `scroll` events can move this viewport. */
  docs: Document[];
}

/**
 * Finds the scroll the element really follows: a scrolling ancestor, else the
 * page. Inside a same-origin frame (the docs preview) that does not scroll
 * itself, it is the scroll of the page holding the frame, mapped into the
 * frame's own coordinates.
 */
function viewportOf(host: HTMLElement): Viewport {
  const doc = host.ownerDocument;
  const win = doc.defaultView ?? window;
  const root = scrollParentOf(host);
  if (root) {
    return {
      top: root.getBoundingClientRect().top,
      height: root.clientHeight,
      scrolled: root.scrollTop,
      max: root.scrollHeight - root.clientHeight,
      framed: false,
      scrollBy: (dy, behavior) => root.scrollTo({ top: root.scrollTop + dy, behavior }),
      docs: [doc],
    };
  }
  let frame: HTMLElement | null = null;
  try {
    frame = win.frameElement as HTMLElement | null;
  } catch {
    frame = null;
  }
  if (frame) {
    const outer = viewportOf(frame);
    return {
      ...outer,
      top: outer.top - frame.getBoundingClientRect().top,
      framed: true,
      docs: [doc, ...outer.docs],
    };
  }
  return {
    top: 0,
    height: win.innerHeight,
    scrolled: win.scrollY,
    max: doc.documentElement.scrollHeight - win.innerHeight,
    framed: false,
    scrollBy: (dy, behavior) => win.scrollTo({ top: win.scrollY + dy, behavior }),
    docs: [doc],
  };
}

/**
 * Scroll-linked progress for a vertical timeline.
 *
 * Marks the point on every node (`data-tl-anchor`) and returns how far a focus
 * line has travelled down them as a fractional index: `1.4` is 40% of the way
 * from node 1 to node 2. The line sits `focus` of the way down whatever scrolls
 * (the nearest scrolling ancestor, else the page), so the same component works
 * in a page, in a fixed-height panel and in the docs preview.
 *
 * `goTo(i)` scrolls node `i` onto the focus line. When nothing can scroll it
 * just sets the progress, so a click still works.
 */
export function useScrollProgress(
  ref: ElementRef,
  count: number,
  {
    focus = 0.4,
    initial = 0,
    onChange,
  }: { focus?: number; initial?: number; onChange?: (index: number) => void } = {},
) {
  const [progress, setProgress] = useState(initial);
  const reduced = usePrefersReducedMotion();
  const last = Math.max(0, count - 1);
  const active = clamp(Math.floor(progress + 0.001), 0, last);

  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);
  const mounted = useRef(false);
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    onChangeRef.current?.(active);
  }, [active]);

  useEffect(() => {
    const host = ref.current;
    if (!host) return;
    let frame = 0;
    let visible = true;

    const measure = () => {
      frame = 0;
      if (!visible) return;
      const anchors = host.querySelectorAll<HTMLElement>("[data-tl-anchor]");
      if (anchors.length === 0) return;
      const view = viewportOf(host);
      // Nothing scrolls: leave the progress to goTo().
      if (view.max <= 4) return;
      const focusY = view.top + view.height * focus;
      const ys = Array.from(anchors, (a) => {
        const r = a.getBoundingClientRect();
        return r.top + r.height / 2;
      });
      let p = 0;
      if (focusY >= ys[ys.length - 1]) p = ys.length - 1;
      else if (focusY > ys[0]) {
        for (let i = 0; i < ys.length - 1; i++) {
          if (focusY <= ys[i + 1]) {
            p = i + (focusY - ys[i]) / (ys[i + 1] - ys[i] || 1);
            break;
          }
        }
      }
      // The last node can sit below the focus line even at the end of the
      // scroll, so the end of the scroll counts as having reached it. A framed
      // timeline sits mid-page, so the end of the page says nothing about it.
      if (!view.framed && view.scrolled >= view.max - 2) p = ys.length - 1;
      const next = Math.round(p * 100) / 100;
      setProgress((prev) => (prev === next ? prev : next));
    };

    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };

    const observer =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            if (visible) schedule();
          })
        : null;
    observer?.observe(host);

    // `scroll` does not bubble, but capturing on a document hears its page and
    // every scrolling panel with one listener. A framed timeline also listens
    // to the page that holds the frame.
    const docs = viewportOf(host).docs;
    const wins: Window[] = [];
    for (const d of docs) if (d.defaultView) wins.push(d.defaultView);
    docs.forEach((d) =>
      d.addEventListener("scroll", schedule, { passive: true, capture: true }),
    );
    wins.forEach((w) => w.addEventListener("resize", schedule));
    const resize =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null;
    resize?.observe(host);
    schedule();

    return () => {
      if (frame) cancelAnimationFrame(frame);
      observer?.disconnect();
      resize?.disconnect();
      docs.forEach((d) => d.removeEventListener("scroll", schedule, { capture: true }));
      wins.forEach((w) => w.removeEventListener("resize", schedule));
    };
  }, [ref, focus, count]);

  const goTo = useCallback(
    (index: number) => {
      const host = ref.current;
      if (!host) return;
      const i = clamp(index, 0, last);
      const anchors = host.querySelectorAll<HTMLElement>("[data-tl-anchor]");
      const target = anchors[i];
      if (!target) return;
      const view = viewportOf(host);
      if (view.max <= 4) {
        setProgress(i);
        return;
      }
      const r = target.getBoundingClientRect();
      const delta = r.top + r.height / 2 - (view.top + view.height * focus);
      view.scrollBy(delta + 1, reduced ? "auto" : "smooth");
    },
    [ref, focus, last, reduced],
  );

  return { progress, active, goTo };
}

/**
 * Wheel, arrow keys and vertical drag for a timeline that steps through its
 * items rather than scrolling. The wheel only steps while there is somewhere to
 * go, so the page keeps scrolling at either end.
 */
export function useStepControls(
  ref: ElementRef,
  { count, active, onStep }: { count: number; active: number; onStep: (delta: number) => void },
) {
  const state = useRef({ count, active, onStep });
  useEffect(() => {
    state.current = { count, active, onStep };
  }, [count, active, onStep]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let lastWheel = 0;
    let down = false;
    let moved = false;
    let startY = 0;

    const onWheel = (e: WheelEvent) => {
      if (Math.abs(e.deltaY) < Math.abs(e.deltaX)) return;
      const dir = e.deltaY > 0 ? 1 : -1;
      const next = state.current.active + dir;
      if (next < 0 || next >= state.current.count) return;
      e.preventDefault();
      const now = performance.now();
      if (now - lastWheel < 380) return;
      lastWheel = now;
      state.current.onStep(dir);
    };
    const onKey = (e: KeyboardEvent) => {
      const step =
        e.key === "ArrowDown" || e.key === "ArrowRight"
          ? 1
          : e.key === "ArrowUp" || e.key === "ArrowLeft"
            ? -1
            : e.key === "Home"
              ? -state.current.count
              : e.key === "End"
                ? state.current.count
                : 0;
      if (!step) return;
      e.preventDefault();
      state.current.onStep(step);
    };
    const onDown = (e: PointerEvent) => {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      down = true;
      moved = false;
      startY = e.clientY;
    };
    const onMove = (e: PointerEvent) => {
      if (!down) return;
      const dy = e.clientY - startY;
      if (Math.abs(dy) >= 44) {
        state.current.onStep(dy < 0 ? 1 : -1);
        startY = e.clientY;
        moved = true;
      }
    };
    const onUp = () => {
      down = false;
    };
    // A drag that stepped should not also click the item it ended on.
    const onClick = (e: MouseEvent) => {
      if (moved) {
        e.stopPropagation();
        e.preventDefault();
        moved = false;
      }
    };

    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("keydown", onKey);
    el.addEventListener("pointerdown", onDown);
    el.addEventListener("click", onClick, true);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      el.removeEventListener("wheel", onWheel);
      el.removeEventListener("keydown", onKey);
      el.removeEventListener("pointerdown", onDown);
      el.removeEventListener("click", onClick, true);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [ref]);
}
